export function schematic(kind){return `<svg viewBox="0 0 310 200" role="img" aria-label="Illustrative ${kind} engineering schematic"><defs><marker id="arrow-${kind}" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="currentColor"/></marker></defs><g fill="none" stroke="#a4bbc6" stroke-width="1.6" stroke-linejoin="round">${(drawings[kind]||drawings.chassis).replaceAll('class="flow"',`class="flow" marker-end="url(#arrow-${kind})"`)}</g></svg>`}
